        scrollFraction = geometry?.scrollFraction ?: 0f,
        regions = ocrRegions,
        engineUsed = engineName,
        imageWidth = result.imageWidth,
        imageHeight = result.imageHeight,

metadata.output:
                partials.close()
            }
        }
        if (streaming) {
            for (region in partials) {
                if (myGen != generation || job?.isActive != true) {
