    // размер: иначе голубая подсветка вылезает за текст/экран.
    .filter { b ->
        val bb = b.boundingBox
        bb.left >= -0.001f && bb.top >= -0.001f &&
            bb.right <= 1.001f && bb.bottom <= 1.001f &&
            (bb.right - bb.left) > 0.02f &&
            (bb.bottom - bb.top) > 0.01f
    }
