/**
 * Помечает уже озвученную потоковым проходом реплику прочитанной в карте
 * кадра: на неё должна гореть галочка, а не «читается сейчас».
 *
 * Ключи реплик кэшируются по списку кадра: [lineKey] гоняет регулярку по
 * всему тексту, а раньше он пересчитывался для КАЖДОГО региона на КАЖДУЮ
 * озвученную реплику — на странице из 40 баблов это 1600 нормализаций
 * текста вместо сорока.
 */
private fun markSpokenInFrame(text: String) {
    val key = lineKey(text)
    val current = _frameRegions.value
    val keys = frameKeys(current)
    _frameRegions.value = current.mapIndexed { index, region ->
        if (keys[index] == key) {
            region.copy(state = FrameRegion.State.DONE)
        } else {
            region
        }
    }
}

private var frameKeysSource: List<FrameRegion>? = null
private var frameKeysCache: Array<String> = emptyArray()

@Synchronized
private fun frameKeys(regions: List<FrameRegion>): Array<String> {
    if (regions === frameKeysSource) return frameKeysCache
    val keys = Array(regions.size) { lineKey(regions[it].text) }
    frameKeysSource = regions
    frameKeysCache = keys
    return keys
}

