private val MULTI_NEWLINE = Regex("\n{2,}")
private val SENTENCE_SPLIT = Regex("(?<=[.!?…])\\s+")

private fun splitSentences(text: String): List<String> = text
    .replace(MULTI_NEWLINE, "\n").split(SENTENCE_SPLIT)
    .map { it.trim() }.filter { it.isNotBlank() }

private fun countSentences(text: String): Int {
    if (text.isBlank()) return 0
    val normalized = text.replace(MULTI_NEWLINE, "\n")
    val matcher = SENTENCE_SPLIT.matcher(normalized)
    var count = 0
    var start = 0
    while (matcher.find()) {
        if (hasNonWhitespace(normalized, start, matcher.start())) count++
        start = matcher.end()
    }
    if (hasNonWhitespace(normalized, start, normalized.length)) count++
    return count
}

private fun hasNonWhitespace(s: String, from: Int, to: Int): Boolean {
    for (i in from until to) if (!s[i].isWhitespace()) return true
    return false
}

fun main() {
    val cases = listOf(
        "", "   ", "Hello.", "Hello. World!", "A\n\n\nB", "  \n  ", "one two three",
        "Привет! Как дела?\nВсё хорошо.", "Да... Нет.", "trailing space   ",
        "....", "a b c d e f", "End.", "Multi\nline\nsentence",
    )
    var bad = 0
    for (c in cases) {
        val a = splitSentences(c).size
        val b = countSentences(c)
        if (a != b) { bad++; println("MISMATCH [$c] split=$a count=$b") }
    }
    println(if (bad == 0) "ALL OK (${cases.size} cases)" else "$bad mismatches")
}
