        // Сторож живости: опрос редкий (200 мс), потому что это грубая
        // проверка «идёт ли ещё чтение», а не синхронизация с голосом.
        val watcher = launch {
            while (true) {
                if (!speechAlive()) {
                    lost.complete(Unit)
                    return@launch
                }
                delay(200)
            }
        }
        try {
            val waiter = async { block() }
            select {
                waiter.onAwait { false }
                lost.onAwait { true }
            }
        } finally {
            watcher.cancel()
