mkdir -p /tmp/opencode/bench && cat > /tmp/opencode/bench/B.kt <<'EOF'
private fun trigramKey(s: String, i: Int): Long =
    (s[i].code.toLong() shl 32) or (s[i + 1].code.toLong() shl 16) or s[i + 2].code.toLong()

fun newSim(a: String, b: String): Float {
    if (a.length < 3 || b.length < 3) return if (a == b) 1f else 0f
    val ta = HashSet<Long>((a.length * 4 / 3) + 8)
    for (i in 0..a.length - 3) ta.add(trigramKey(a, i))
    var common = 0
    val total = b.length - 2
    for (i in 0..b.length - 3) if (trigramKey(b, i) in ta) common++
    return if (total <= 0) 0f else common.toFloat() / total
}

fun oldSim(a: String, b: String): Float {
    if (a.length < 3 || b.length < 3) return if (a == b) 1f else 0f
    val ta = HashSet<String>(a.length)
    for (i in 0..a.length - 3) ta.add(a.substring(i, i + 3))
    var common = 0
    var total = 0
    for (i in 0..b.length - 3) { total++; if (b.substring(i, i + 3) in ta) common++ }
    return if (total == 0) 0f else common.toFloat() / total
}

fun main() {
    val rnd = java.util.Random(7)
    val pool = (' ' to 'z').toList() + listOf('!','?','-','.','\\u0410','\\u044F','1','9')
    fun rndStr(n: Int) = buildString { repeat(n) { append(pool[rnd.nextInt(pool.size)]) } }
    val history = List(600) { rndStr(20 + rnd.nextInt(40)) }
    val frames = List(40) { rndStr(20 + rnd.nextInt(40)) }
    // проверка идентичности результатов
    var maxDiff = 0f
    for (f in frames) for (h in history) {
        val d = kotlin.math.abs(newSim(h, f) - oldSim(h, f))
        if (d > maxDiff) maxDiff = d
    }
    println("max similarity delta: $maxDiff")

    fun run(sim: (String, String) -> Float): Long {
        val t = System.nanoTime()
        var acc = 0f
        for (r in 0 until 20) for (f in frames) for (h in history) acc += sim(h, f)
        val dt = System.nanoTime() - t
        check(acc >= 0f)
        return dt
    }
    run(::oldSim); run(::newSim)
    val old = run(::oldSim); val nw = run(::newSim)
    println("old=${old/1_000_000}ms new=${nw/1_000_000}ms  speedup=${"%.1f".format(old.toDouble()/nw)}x")
}
EOF
