 * шага есть исход, а конец главы распознаётся и проговаривается.
 */
private fun readCurrentPage(thenAdvance: Boolean) {
    autoReadLoop?.cancel()
    autoReadLoop = lifecycleScope.launchIO { runAutoReadChapter(thenAdvance) }
}

