/**
 * Разбирает электронную книгу любого формата в список глав (название, текст).
 *
 * Поддерживаются:
 *  • txt / md / markdown / rtf / srt / vtt / json и любые другие — текст с автоопределением кодировки;
 *  • fb2 — XML FictionBook (главы = разделы, текст = <p>);
 *  • html / htm — заголовки h1..h4 становятся главами;
 *  • epub — zip (container.xml → OPF → spine), каждая запись spine — глава;
 *  • docx — zip (word/document.xml), абзацы <w:p> конкатенируются;
 *  • pdf — рендеринг страниц через Android PdfRenderer + OCR (если доступен).
 *
 * Извлекает метаданные: название, автор, описание, обложка (для EPUB/FB2/PDF).
 */
object BookParser {

    class UnsupportedBookException(message: String) : Exception(message)

    /**
     * Метаданные книги — аналог [tachiyomi.domain.manga.model.Manga]
     * для локальных электронных книг.
     */
    data class BookMetadata(
        val title: String,
        val author: String? = null,
        val description: String? = null,
        val genre: List<String>? = null,
        val coverImage: ByteArray? = null,
        val language: String? = null,
        val publisher: String? = null,
        val year: Int? = null,
    ) {
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is BookMetadata) return false
            return title == other.title && author == other.author
        }
        override fun hashCode(): Int = title.hashCode() * 31 + (author?.hashCode() ?: 0)
    }

    data class ParsedBook(
        val metadata: BookMetadata,
        val chapters: List<BookChapter>,
    ) {
        constructor(title: String, chapters: List<Pair<String, String>>) : this(
            metadata = BookMetadata(title = title),
            chapters = chapters.mapIndexed { idx, (name, text) ->
                BookChapter.create(
                    index = idx,
                    bookId = "",
                    title = name,
                    text = text,
                )
            },
        )
    }

    private val TEXT_EXTS = setOf(
        "txt", "md", "markdown", "log", "text", "lrc", "srt", "vtt",
        "ini", "conf", "cfg", "csv", "json", "yaml", "yml", "xml", "rtf",
    )

    private val ZIP_EXTS = setOf("epub", "docx")

    private val PDF_MAGIC = byteArrayOf(0x25, 0x50, 0x44, 0x46, 0x2D) // %PDF-
    private val RTF_MAGIC = byteArrayOf(0x7B, 0x5C, 0x72, 0x74, 0x66) // RTF: {\rtf
    private val ZIP_LOCAL_MAGIC = byteArrayOf(0x50, 0x4B, 0x03, 0x04) // PK\x03\x04
    private val ZIP_EMPTY_MAGIC = byteArrayOf(0x50, 0x4B, 0x05, 0x06) // PK\x05\x06
    private val ZIP_SPANNED_MAGIC = byteArrayOf(0x50, 0x4B, 0x07, 0x08) // PK\x07\x08

    fun parse(bookFile: UniFile, bookId: String = bookFile.uri.toString()): ParsedBook {
        val input = bookFile.openInputStream() ?: throw UnsupportedBookException("Не удалось открыть файл книги")
        val bytes = input.use { stream ->
            val buf = java.io.ByteArrayOutputStream()
            val tmp = ByteArray(8192)
            var totalRead = 0L
            while (true) {
                val read = stream.read(tmp)
                if (read < 0) break
                totalRead += read
                if (totalRead > 40_000_000L) {
                    throw UnsupportedBookException("Файл слишком большой для чтения (более 40 МБ)")
                }
                buf.write(tmp, 0, read)
            }
            buf.toByteArray()
        }
        if (bytes.isEmpty()) throw UnsupportedBookException("Файл пуст")
        val name = bookFile.name.orEmpty().substringBeforeLast('.').ifBlank { "Книга" }
        val ext = bookFile.extension().lowercase()
        // Формат определяется ПО СОДЕРЖИМОМУ, а не по расширению: бинарный
        // файл с расширением .pdf не должен трактоваться как PDF.
        val format = detectFormat(ext, bytes)

        return try {
            when (format) {
                "pdf" -> parsePdf(bytes, name, bookId)
                "fb2" -> parseFb2(bytes, name, bookId)
                "html" -> parseHtml(bytes, name, bookId)
                "epub" -> parseEpub(bytes, bookId)
                "docx" -> parseDocx(bytes, name, bookId)

package eu.kanade.tachiyomi.data.books

/**
 * Глава книги — поддерживает вложенность: Том → Глава → Страницы.
 *
 * Два режима:
 *  • **Текстовые главы** (EPUB, FB2, HTML, DOCX, TXT) — текст хранится в [text],
 *    страниц нет.
 *  • **Страницы** (PDF, DJVU) — глава содержит список [pages], текст каждой
 *    страницы хранится в [BookPage.text].
 *
 * Поддерживает структуру ранобэ/книг:
 *  • Том 1 → Глава 1: Пролог → страницы 1-5 (обложки/титулы тоже показываются)
 *  • Том 1 → Глава 1: Пролог → страницы 6-12 (текст главы)
 *
 * @param isPageBased true = страницы (PDF), false = текстовые главы (EPUB/FB2/...)
 * @param volume Номер тома (null если нет томов).
 * @param chapter Номер главы (null если нет нумерации).
 * @param subChapter Подглава / секция.
 */
data class BookChapter(
    val id: Long,
    val bookId: String,
    val name: String,
    val isPageBased: Boolean = false,
    val volume: Int? = null,
    val chapter: Int? = null,
    val subChapter: Int? = null,
    val URL: String = "",
    val chapterNumber: Double = -1.0,
    val scanlator: String? = null,
    val dateUpload: Long = System.currentTimeMillis(),
    val read: Boolean = false,
    val bookmark: Boolean = false,
    val lastPageRead: Long = 0,
    val text: String = "",
    val pages: List<BookPage> = emptyList(),
) {
    val isRecognizedNumber: Boolean
        get() = chapterNumber >= 0.0

    /** Количество страниц в главе (для page-based). */
    val pageCount: Int get() = pages.size

    /** Страницы главы (обложки/титулы тоже показываются, не пропускаются). */
    val readablePages: List<BookPage>
        get() = pages

    /** Текст главы: для text-based берётся из [text], для page-based конкатенируется из страниц. */
    val resolvedText: String
        get() = if (isPageBased) {
            readablePages.joinToString("\n\n") { it.text }.ifBlank { text }
        } else {
            text
        }

    /**
     * Отображаемое название.
     * Примеры:
     *  • PDF без оглавления: "Страница 3 из 120"
     *  • EPUB: "Том 1, Глава 5: Пролог"
     *  • PDF с оглавлением: "Глава 1: Пролог (стр. 3-12)"
     */
    val displayTitle: String
        get() = buildString {
            if (isPageBased) {
                if (volume != null || chapter != null) {
                    // Есть оглавление — показываем структуру
                    if (volume != null) append("Том $volume")
                    if (chapter != null) {
                        if (isNotEmpty()) append(", ")
                        append("Глава $chapter")
                    }
                    if (subChapter != null) append(".$subChapter")
                    if (name.isNotBlank() && name != "Страница ${pages.firstOrNull()?.pageNumber ?: 1}") {
                        if (isNotEmpty()) append(": ")
                        append(name)
                    }
                    // Диапазон страниц
                    val first = pages.firstOrNull()?.pageNumber
                    val last = pages.lastOrNull()?.pageNumber
                    if (first != null && last != null && first != last) {
                        append(" (стр. $first–$last)")
                    }
                } else {
                    // Нет оглавления — просто номер страницы
                    val p = pages.firstOrNull()?.pageNumber ?: (id.toInt() + 1)
                    val total = pages.firstOrNull()?.totalPages ?: p
                    append("Страница $p из $total")
                }
            } else {
                // Текстовые главы
                if (volume != null) append("Том $volume")
                if (chapter != null) {
                    if (isNotEmpty()) append(", ")
                    append("Глава $chapter")
                }
                if (subChapter != null) append(".$subChapter")
                if (isNotEmpty()) append(": ")
                append(name.ifBlank { "Текст" })
            }
        }

    /** Строка для шапки читалки. */
    val headerLine: String
        get() = if (isPageBased) {
            if (volume != null || chapter != null) {
                displayTitle
            } else {
                val p = pages.firstOrNull()?.pageNumber ?: (id.toInt() + 1)
                val total = pages.firstOrNull()?.totalPages ?: p
                "Страница $p из $total"
            }
        } else {
            displayTitle
        }

    companion object {
        /**
         * Создаёт текстовую главу (EPUB, FB2, HTML, DOCX, TXT).
         */
        fun create(
            index: Int,
            bookId: String,
            title: String,
            volume: Int? = null,
            chapter: Int? = null,
            subChapter: Int? = null,
            url: String = "",
            scanlator: String? = null,
            text: String = "",
        ): BookChapter {
            val chapterNumber = when {
                chapter != null && volume != null -> volume * 100.0 + chapter
                chapter != null -> chapter.toDouble()
                else -> index.toDouble()
            }
            return BookChapter(
                id = index.toLong(),
                bookId = bookId,
                name = title,
                isPageBased = false,
                volume = volume,
                chapter = chapter,
                subChapter = subChapter,
                URL = url,
                chapterNumber = chapterNumber,
                scanlator = scanlator,
                text = text,
            )
        }

        /**
         * Создаёт главу-страницу (PDF без оглавления — просто страница).
         */
        fun createPage(
            index: Int,
            bookId: String,
            pageNumber: Int,
            totalPages: Int,
            text: String = "",
        ): BookChapter {
            return BookChapter(
                id = index.toLong(),
                bookId = bookId,
                name = "Страница $pageNumber",
                isPageBased = true,
                chapterNumber = index.toDouble(),
                pages = listOf(
                    BookPage(
                        pageNumber = pageNumber,
                        totalPages = totalPages,
                        text = text,
                    ),
                ),
            )
        }

        /**
         * Создаёт главу-раздел с несколькими страницами (PDF с оглавлением).
         *
         * @param startPage Первая страница главы (1-based).
         * @param endPage Последняя страница главы (включительно).
         */
        fun createSection(
            index: Int,
            bookId: String,
            title: String,
            startPage: Int,
            endPage: Int,
            totalPages: Int = endPage,
            volume: Int? = null,
            chapter: Int? = null,
            subChapter: Int? = null,
            scanlator: String? = null,
        ): BookChapter {
            val chapterNumber = when {
                chapter != null && volume != null -> volume * 100.0 + chapter
                chapter != null -> chapter.toDouble()
                else -> index.toDouble()
            }
            val pageList = (startPage..endPage).map { p ->
                BookPage(pageNumber = p, totalPages = totalPages)
            }
            return BookChapter(
                id = index.toLong(),
                bookId = bookId,
                name = title,
                isPageBased = true,
                volume = volume,
                chapter = chapter,
                subChapter = subChapter,
                chapterNumber = chapterNumber,
                scanlator = scanlator,
                pages = pageList,
            )
        }
    }
}

/**
 * Одна страница книги (для PDF/DJVU).
 *
 * @param pageNumber Порядковый номер страницы в файле (1-based).
 * @param totalPages Общее число страниц в файле.
 * @param text Текст страницы. Для PDF/DJVU он пуст до локального распознавания:
